service-call.in-map:
{eventType:(status === 'completed' ? 'exportCompleted' : 'writeFailed'), requestName:requestName,
                        status:status, protocol:'Device Config Export', routeId:'run-device-config-export', rowCount:rowCount,
                        message:(status === 'completed' ? ('Device configuration export completed for rule set ' + deviceRuleSetId + '.') : errorMessage)}

set.from:
Array.from(requestList).sort((a, b) => {
                    const key = value => value == null ? 999999 : (typeof value.toNumber === 'function' ? value.toNumber() : Number(value));
                    return (key(a.priority) - key(b.priority)) || (key(a.sequenceNum) - key(b.sequenceNum))
                        || (a.requestName < b.requestName ? -1 : (a.requestName > b.requestName ? 1 : 0));
                }).map(r => r.requestName)
